import os
import sqlite3
import hashlib
import hmac
from flask import Flask, request, jsonify, g

app = Flask(__name__)

DB_PATH = os.environ.get('DB_PATH', '/data/app.db')
SECRET_KEY = os.environ.get('SECRET_KEY', 'changeme')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DB_PATH)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DB_PATH)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        password_hash TEXT NOT NULL,
        role TEXT DEFAULT 'user',
        api_key TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        details TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.commit()
    db.close()

def verify_token(token):
    """Verify HMAC token for admin endpoints"""
    if not token:
        return False
    parts = token.split(':')
    if len(parts) != 2:
        return False
    payload, sig = parts
    expected = hmac.new(SECRET_KEY.encode(), payload.encode(), hashlib.sha256).hexdigest()
    return hmac.compare_digest(sig, expected)

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by username pattern"""
    query = request.args.get('q', '')
    role_filter = request.args.get('role', '')

    # Build search query
    sql = "SELECT id, username, role FROM users WHERE username LIKE '%" + query + "%'"

    if role_filter:
        sql += " AND role = '" + role_filter + "'"

    db = get_db()
    try:
        results = db.execute(sql).fetchall()
        users = [{'id': r['id'], 'username': r['username'], 'role': r['role']} for r in results]
        return jsonify({'users': users, 'count': len(users)})
    except Exception as e:
        app.logger.error(f"Search error: {e}")
        return jsonify({'error': 'Search failed'}), 500

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    """Get user details by ID"""
    db = get_db()
    user = db.execute('SELECT id, username, role FROM users WHERE id = ?', (user_id,)).fetchone()
    if user:
        return jsonify({'id': user['id'], 'username': user['username'], 'role': user['role']})
    return jsonify({'error': 'Not found'}), 404

@app.route('/api/admin/users', methods=['GET'])
def admin_list_users():
    """Admin endpoint - list all users with sensitive data"""
    auth = request.headers.get('Authorization', '')
    if not verify_token(auth.replace('Bearer ', '')):
        return jsonify({'error': 'Unauthorized'}), 401

    db = get_db()
    results = db.execute('SELECT id, username, role, api_key FROM users').fetchall()
    users = [{'id': r['id'], 'username': r['username'], 'role': r['role'], 'api_key': r['api_key']} for r in results]
    return jsonify({'users': users})

@app.route('/api/audit', methods=['GET'])
def get_audit_log():
    """Retrieve audit log entries"""
    limit = request.args.get('limit', '50')
    db = get_db()
    # Parameterized here but the search endpoint above is not
    results = db.execute('SELECT * FROM audit_log ORDER BY timestamp DESC LIMIT ?', (int(limit),)).fetchall()
    logs = [{'id': r['id'], 'action': r['action'], 'details': r['details']} for r in results]
    return jsonify({'logs': logs})

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
